  function dashboardMetrics(list){const sum=predicate=>list.filter(predicate).reduce((s,x)=>s+(Number(x.amount)||0),0);const income=sum(x=>x.type==='Salary'||x.type==='Side Income'||x.type==='Investment Profit');const expense=sum(x=>x.type==='Daily Expense');const investment=sum(x=>x.type==='Investment');return {income,expense,investment,savings:income-expense-investment}}
