  function renderDashboardOutstanding(){const records=people.map(person=>({person,net:outstanding(person.id)})),receives=records.filter(x=>x.net>0),gives=records.filter(x=>x.net<0);$('#dashboardReceiveTotal').textContent=rupees(receives.reduce((s,x)=>s+x.net,0));$('#dashboardGiveTotal').textContent=rupees(gives.reduce((s,x)=>s+Math.abs(x.net),0));$('#dashboardReceiveCount').textContent=(receives.length===1?T.personCount:T.peopleCount).replace('{count}',receives.length);$('#dashboardGiveCount').textContent=(gives.length===1?T.personCount:T.peopleCount).replace('{count}',gives.length);const top=[...receives.map(x=>({...x,amount:x.net,status:T.willReceiveShort})),...gives.map(x=>({...x,amount:Math.abs(x.net),status:T.haveToGiveShort}))].sort((a,b)=>b.amount-a.amount).slice(0,3);$('#dashboardTopPeople').innerHTML=top.map(x=>`<button type="button" class="dashboard-person-row" data-person-id="${esc(x.person.id)}"><span>${esc(x.person.name)}</span><small class="${x.net>0?'positive':'negative'}">${x.status}</small><strong class="${x.net>0?'positive':'negative'}">${rupees(x.amount)}</strong></button>`).join('')||`<p class="dashboard-empty-line">${T.noUdharYet}</p>`;$('#dashboardTopPeople').querySelectorAll('[data-person-id]').forEach(b=>b.addEventListener('click',()=>{activePersonId=b.dataset.personId;showScreen('outstanding')}))}
  function investmentRecords(){const map=new Map();transactions.filter(x=>['Investment','Investment Profit','Investment Loss'].includes(x.type)).forEach(x=>{const name=x.investmentName||T.noInvestmentNames;if(!map.has(name))map.set(name,[]);map.get(name).push(x)});return [...map].map(([name,entries])=>{const sum=type=>entries.filter(x=>x.type===type).reduce((s,x)=>s+(Number(x.amount)||0),0),invested=sum('Investment'),profit=sum('Investment Profit'),loss=sum('Investment Loss'),last=[...entries].sort((a,b)=>b.date.localeCompare(a.date)||(b.createdAt||'').localeCompare(a.createdAt||''))[0],kind=entries.find(x=>x.type==='Investment'&&x.investmentKind)?.investmentKind||entries.find(x=>x.investmentKind)?.investmentKind||'Other';return {name,entries,invested,profit,loss,net:profit-loss,last,kind}})}
