  function startInvestmentEntry(type){if(!activeInvestmentName)return;investmentReturnName=activeInvestmentName;investmentNameInput=activeInvestmentName;showScreen('entry');resetForm();setKind(type==='Investment Profit'?'credit':'debit');selectedType=type;renderTypeChips();document.querySelectorAll('#typeChips .chip').forEach(c=>c.classList.toggle('selected',c.textContent===displayType(type)));renderDynamicFields();if($('#investmentName'))$('#investmentName').value=activeInvestmentName}
  function reminderDueDate(x){return String(x.dueDate||'').slice(0,10)}
  function reminderDayDifference(dueDate){const today=new Date(`${todayISO()}T00:00:00`),due=new Date(`${dueDate}T00:00:00`);return Math.round((due-today)/86400000)}
  function reminderPersonName(x){return people.find(p=>p.id===x.person?.id)?.name||x.person?.name||T.person}
  function reminderRelativeDate(x){const days=reminderDayDifference(reminderDueDate(x));if(days===0)return T.today;if(days===1)return T.reminderInOneDay;if(days>1)return T.reminderInDays.replace('{count}',days);if(days===-1)return T.reminderOverdueOneDay;return T.reminderOverdueBy.replace('{count}',Math.abs(days))}
  function renderDashboardReminders(){const pending=reminders.filter(x=>x.status==='Pending'),today=todayISO(),overdue=pending.filter(x=>reminderDueDate(x)<today),upcoming=pending.filter(x=>reminderDueDate(x)>=today).sort((a,b)=>reminderDueDate(a).localeCompare(reminderDueDate(b))||(a.time||'').localeCompare(b.time||'')).slice(0,3);$('#overdueReminderCount').textContent=String(overdue.length);$('#overdueReminderCount').classList.toggle('negative',overdue.length>0);$('#upcomingReminderList').innerHTML=upcoming.map(x=>`<div class="dashboard-reminder-row"><span><strong>${esc(reminderPersonName(x))}</strong><small class="${x.type==='receive'?'positive':'negative'}">${x.type==='receive'?T.toReceive:T.toGive} · ${rupees(x.amount)}</small></span><small>${esc(dateLabel(reminderDueDate(x)))} · ${esc(reminderRelativeDate(x))}</small></div>`).join('')||`<p class="dashboard-empty-line">${esc(T.noUpcomingReminders)}</p>`}
  function renderReminderBanner(){if(!$('#reminderBanner'))return;const pending=reminders.filter(x=>x.status==='Pending'),today=todayISO(),dueToday=pending.filter(x=>reminderDueDate(x)===today).length,overdue=pending.filter(x=>reminderDueDate(x)<today).length;$('#reminderBanner').hidden=dueToday+overdue===0;if(!$('#reminderBanner').hidden)$('#reminderBannerText').textContent=T.reminderBannerText.replace('{today}',dueToday).replace('{overdue}',overdue)}
  function renderReminderScreen(){const pending=reminders.filter(x=>x.status==='Pending');$('#reminderReceiveTotal').textContent=rupees(pending.filter(x=>x.type==='receive').reduce((s,x)=>s+Number(x.amount||0),0));$('#reminderGiveTotal').textContent=rupees(pending.filter(x=>x.type==='give').reduce((s,x)=>s+Number(x.amount||0),0));document.querySelectorAll('.reminder-tab').forEach(b=>b.classList.toggle('active',b.dataset.reminderTab===reminderTab));let rows=reminders.filter(x=>{const date=reminderDueDate(x);return reminderTab==='Done'?x.status==='Done':x.status==='Pending'&&(reminderTab==='Today'?date===todayISO():reminderTab==='Upcoming'?date>todayISO():date<todayISO())});rows.sort((a,b)=>reminderTab==='Done'?b.dueDate.localeCompare(a.dueDate):a.dueDate.localeCompare(b.dueDate)||(a.time||'').localeCompare(b.time||''));$('#reminderList').innerHTML=rows.map(x=>{const person=reminderPersonName(x),overdue=reminderTab==='Overdue',typeLabel=x.type==='receive'?T.toReceive:T.toGive,relative=x.status==='Done'?T.done:reminderRelativeDate(x);return `<article class="reminder-row ${overdue?'overdue':''}"><div class="reminder-row-main"><strong>${esc(person)}</strong><span class="reminder-type ${x.type==='receive'?'positive':'negative'}">${esc(typeLabel)}</span><small>${esc(dateLabel(reminderDueDate(x),{day:'numeric',month:'short',year:'numeric'}))}${x.time?` · ${esc(x.time)}`:''} · ${esc(relative)}</small>${x.note?`<small class="reminder-note">${esc(x.note)}</small>`:''}</div><strong class="reminder-row-amount ${x.type==='receive'?'positive':'negative'}">${rupees(x.amount)}</strong><div class="reminder-actions">${x.status==='Pending'?`<button type="button" data-reminder-action="done" data-reminder-id="${esc(x.id)}">${T.markDone}</button><button type="button" data-reminder-action="edit" data-reminder-id="${esc(x.id)}">${T.edit}</button><button type="button" data-reminder-action="delete" data-reminder-id="${esc(x.id)}">${T.delete}</button><button type="button" data-reminder-action="calendar" data-reminder-id="${esc(x.id)}">${T.addToCalendar}</button><div class="reminder-snooze">${T.snooze}: <button type="button" data-reminder-action="snooze" data-days="1" data-reminder-id="${esc(x.id)}">${T.tomorrow}</button><button type="button" data-reminder-action="snooze" data-days="3" data-reminder-id="${esc(x.id)}">${T.threeDays}</button><button type="button" data-reminder-action="snooze" data-days="7" data-reminder-id="${esc(x.id)}">${T.nextWeek}</button></div>`:`<span class="reminder-done-label">${T.done}</span>`}</div></article>`}).join('');$('#reminderEmpty').hidden=rows.length>0;$('#reminderEmpty').textContent=T[`empty${reminderTab}`]||T.noReminders;$('#reminderList').querySelectorAll('[data-reminder-action]').forEach(button=>button.addEventListener('click',()=>handleReminderAction(button.dataset.reminderAction,button.dataset.reminderId,Number(button.dataset.days)||0)));renderReminderBanner()}
  function fillReminderPeople(selectedId=''){const select=$('#reminderPerson');select.innerHTML=`<option value="">${esc(T.choosePerson)}</option>`+people.slice().sort((a,b)=>a.name.localeCompare(b.name)).map(p=>`<option value="${esc(p.id)}">${esc(p.name)}</option>`).join('');select.value=selectedId}
  function openReminderForm({reminder=null,personId='',amount='',type='receive'}={}){reminderEditId=reminder?.id||null;$('#reminderForm').hidden=false;$('#reminderList').hidden=true;$('#reminderEmpty').hidden=true;$('#addReminderButton').hidden=true;$('#reminderFormTitle').textContent=reminder?T.editReminder:T.addReminder;fillReminderPeople(reminder?.person?.id||personId);$('#reminderType').value=reminder?.type||type;$('#reminderAmount').value=reminder?formatMoney(reminder.amount):amount?formatMoney(amount):'';$('#reminderDueDate').value=reminder?.dueDate||todayISO();$('#reminderTime').value=reminder?.time||'';$('#reminderNote').value=reminder?.note||'';$('#reminderRepeat').value=reminder?.repeat||'None';$('#reminderStatus').value=reminder?.status||'Pending';$('#reminderFormError').textContent='';$('#reminderForm').scrollIntoView({behavior:'smooth',block:'start'})}
  function closeReminderForm(){reminderEditId=null;$('#reminderForm').hidden=true;$('#reminderList').hidden=false;$('#addReminderButton').hidden=false;$('#reminderForm').reset();renderReminderScreen()}
  function reminderDaysFrom(date,count){const d=new Date(`${date}T00:00:00`);d.setDate(d.getDate()+count);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
  function nextRepeatDate(reminder){const d=new Date(`${reminder.dueDate}T00:00:00`);if(reminder.repeat==='Weekly')d.setDate(d.getDate()+7);else if(reminder.repeat==='Monthly'){const day=d.getDate();d.setDate(1);d.setMonth(d.getMonth()+1);d.setDate(Math.min(day,new Date(d.getFullYear(),d.getMonth()+1,0).getDate()))}return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
  async function markReminderDone(reminder,shouldRefresh=true){reminder.status='Done';await LedgerDB.saveReminder(reminder);if(reminder.repeat&&reminder.repeat!=='None'){let dueDate=nextRepeatDate(reminder);while(dueDate<=todayISO())dueDate=reminder.repeat==='Weekly'?reminderDaysFrom(dueDate,7):nextRepeatDate({...reminder,dueDate});await LedgerDB.saveReminder({...reminder,id:crypto.randomUUID(),dueDate,status:'Pending',createdAt:new Date().toISOString()})}reminders=await LedgerDB.reminders();if(shouldRefresh)refresh()}
  async function handleReminderAction(action,id,days){const reminder=reminders.find(x=>x.id===id);if(!reminder)return;if(action==='done'){if(confirm(T.recordPayment)){pendingReminderPaymentId=id;startReminderPayment(reminder)}else await markReminderDone(reminder)}else if(action==='edit')openReminderForm({reminder});else if(action==='delete'){if(!confirm(T.deleteReminderConfirm))return;await LedgerDB.deleteReminder(id);reminders=await LedgerDB.reminders();refresh()}else if(action==='snooze'){reminder.dueDate=reminderDaysFrom(todayISO(),days);await LedgerDB.saveReminder(reminder);reminders=await LedgerDB.reminders();refresh()}else if(action==='calendar')downloadReminderCalendar(reminder)}
  function startReminderPayment(reminder){returnToOutstandingDetail=false;showScreen('entry');resetForm();const type=reminder.type==='receive'?'Udhar Received Back':'Udhar Repaid',targetKind=reminder.type==='receive'?'credit':'debit',person=people.find(p=>p.id===reminder.person?.id)||reminder.person;setKind(targetKind);selectedType=type;renderTypeChips();document.querySelectorAll('#typeChips .chip').forEach(c=>c.classList.toggle('selected',c.textContent===displayType(type)));renderDynamicFields();if(person)choosePerson(person);$('#amount').value=formatMoney(reminder.amount);$('#note').value=reminder.note||''}
  async function requestReminderNotificationPermission(){if(localStorage.getItem('pocket-ledger-notification-asked'))return;localStorage.setItem('pocket-ledger-notification-asked','1');if(!('Notification'in window))return;if(Notification.permission!=='default')return;if(!confirm(T.notificationPermissionExplain))return;try{await Notification.requestPermission()}catch{}}
  async function createReminderNotification(reminder){if(!('Notification'in window)||Notification.permission!=='granted'||!('serviceWorker'in navigator))return;const body=T.notificationReminderBody.replace('{type}',reminder.type==='receive'?T.toReceive:T.toGive).replace('{person}',reminderPersonName(reminder)).replace('{amount}',rupees(reminder.amount));try{const registration=await navigator.serviceWorker.ready;await registration.showNotification(T.notificationReminderTitle,{body,tag:`pocket-ledger-${reminder.id}-${reminder.dueDate}-${reminder.time||''}`,data:{url:'./'}})}catch{}}
  async function checkDueReminders(){const due=reminders.filter(x=>x.status==='Pending'&&reminderDueTimestamp(x)<=Date.now());if(!due.length)return;let notified=[];try{notified=JSON.parse(localStorage.getItem('pocket-ledger-notified-reminders')||'[]')}catch{}let changed=false;for(const reminder of due){const key=`${reminder.id}:${reminder.dueDate}:${reminder.time||''}`;if(notified.includes(key))continue;await createReminderNotification(reminder);if('Notification'in window&&Notification.permission==='granted'){notified.push(key);changed=true}}if(changed)localStorage.setItem('pocket-ledger-notified-reminders',JSON.stringify(notified.slice(-250)));renderReminderBanner()}
  function reminderDueTimestamp(reminder){const time=reminder.time||'09:00';return new Date(`${reminder.dueDate}T${time}:00`).getTime()}
  function icsEscape(value){return String(value||'').replace(/\\/g,'\\\\').replace(/\n/g,'\\n').replace(/,/g,'\\,').replace(/;/g,'\\;')}
  function downloadReminderCalendar(reminder){const date=reminder.dueDate.replaceAll('-',''),time=(reminder.time||'09:00').replace(':','')+'00',person=reminderPersonName(reminder),title=`${reminder.type==='receive'?T.toReceive:T.toGive} ${rupees(reminder.amount)} · ${person}`,lines=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Pocket Ledger//Offline Reminder//EN','CALSCALE:GREGORIAN','BEGIN:VEVENT',`UID:${reminder.id}@pocket-ledger`,`DTSTAMP:${new Date().toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,'')}`,`DTSTART:${date}T${time}`,`SUMMARY:${icsEscape(title)}`,`DESCRIPTION:${icsEscape(reminder.note||T.udharReminder)}`];if(reminder.repeat==='Weekly')lines.push('RRULE:FREQ=WEEKLY');if(reminder.repeat==='Monthly')lines.push('RRULE:FREQ=MONTHLY');lines.push('BEGIN:VALARM','TRIGGER:PT0M','ACTION:DISPLAY',`DESCRIPTION:${icsEscape(title)}`,'END:VALARM','END:VEVENT','END:VCALENDAR');const blob=new Blob([lines.join('\r\n')],{type:'text/calendar;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`pocket-ledger-reminder-${reminder.id}.ics`;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000)}
  async function saveReminderForm(event){event.preventDefault();const error=$('#reminderFormError'),amount=Number($('#reminderAmount').value.replace(/,/g,'')),person=people.find(x=>x.id===$('#reminderPerson').value);error.textContent='';if(!person){error.textContent=T.reminderPersonRequired;return}if(!Number.isFinite(amount)||amount<=0){error.textContent=T.requiredAmount;return}if(!$('#reminderDueDate').value){error.textContent=T.dueDateRequired;return}const existing=reminders.find(x=>x.id===reminderEditId),value={id:reminderEditId||crypto.randomUUID(),type:$('#reminderType').value,person:{id:person.id,name:person.name},amount,dueDate:$('#reminderDueDate').value,time:$('#reminderTime').value,note:$('#reminderNote').value.trim(),repeat:$('#reminderRepeat').value,status:$('#reminderStatus').value,createdAt:existing?.createdAt||new Date().toISOString()};try{if(!existing&&value.status==='Pending')await requestReminderNotificationPermission();await LedgerDB.saveReminder(value);reminders=await LedgerDB.reminders();closeReminderForm();refresh();showToast(T.saved)}catch(err){error.textContent=T.reminderSaveFailed;console.error(err)}}
