  async function exportBackup({silent=false,share=false}={}){const [savedAccounts,savedTransactions,savedPeople,savedReminders]=await Promise.all([LedgerDB.accounts(),LedgerDB.transactions(),LedgerDB.people(),LedgerDB.reminders()]);const data={app:'Pocket Ledger',version:2,exportedAt:new Date().toISOString(),accounts:savedAccounts,transactions:savedTransactions,people:savedPeople,reminders:savedReminders,categories,investments,settings:{language,theme:localStorage.getItem('pocket-ledger-theme')||'auto',lockDelay:localStorage.getItem('pocket-ledger-lock-delay')||'60000',dashboardMonth,lastBackupAt:localStorage.getItem('pocket-ledger-last-backup')||null}};const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),filename=`pocket-ledger-backup-${todayISO()}.json`;if(share&&navigator.share&&typeof File!=='undefined'){const file=new File([blob],filename,{type:'application/json'});try{if(!navigator.canShare||navigator.canShare({files:[file]})){await navigator.share({files:[file],title:T.backupExport});localStorage.setItem('pocket-ledger-last-backup',new Date().toISOString());if(!silent)showToast(T.backupDownloaded);renderBackupBanner();if(currentScreen==='settings')renderSettingsExtras();return}}catch(error){if(error.name==='AbortError')return}}const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);localStorage.setItem('pocket-ledger-last-backup',new Date().toISOString());renderBackupBanner();if(!silent){showToast(T.backupDownloaded);if(currentScreen==='settings')renderSettingsExtras()}}
  function validateBackup(data){if(!data||data.app!=='Pocket Ledger'||![1,2].includes(data.version))throw new Error(T.backupUnsupported);for(const key of ['transactions','people','accounts','reminders']){if(!Array.isArray(data[key]))throw new Error(T.backupInvalid);if(data[key].some(row=>!row||typeof row!=='object'||!row.id))throw new Error(T.backupInvalid)}if(data.categories!==undefined&&!Array.isArray(data.categories))throw new Error(T.backupInvalid);if(data.investments!==undefined&&!Array.isArray(data.investments))throw new Error(T.backupInvalid);return data}
  async function readBackupFile(file){try{pendingBackup=validateBackup(JSON.parse(await file.text()));$('#restoreSummary').textContent=T.backupSummary.replace('{transactions}',pendingBackup.transactions.length).replace('{people}',pendingBackup.people.length).replace('{accounts}',pendingBackup.accounts.length).replace('{reminders}',pendingBackup.reminders.length);$('#restoreOverlay').hidden=false}catch(error){pendingBackup=null;alert(error.message||T.backupInvalid)}finally{$('#backupFileInput').value=''}}
  async function restoreBackup(mode){if(!pendingBackup)return;const data=pendingBackup;try{if(mode==='replace'){await exportBackup({silent:true});for(const store of ['transactions','people','accounts','reminders'])await LedgerDB.clear(store);for(const row of data.transactions)await LedgerDB.saveTransaction(row);for(const row of data.people)await LedgerDB.savePerson(row);for(const row of data.accounts)await LedgerDB.saveAccount(row);for(const row of data.reminders)await LedgerDB.saveReminder(row);if(Array.isArray(data.categories))categories=data.categories;if(Array.isArray(data.investments))investments=data.investments;if(data.settings?.language&&window.TRANSLATIONS[data.settings.language]){language=data.settings.language;localStorage.setItem('pocket-ledger-language',language)}if(data.settings?.theme)applyTheme(data.settings.theme);if(data.settings?.lockDelay)localStorage.setItem('pocket-ledger-lock-delay',data.settings.lockDelay);if(data.settings?.dashboardMonth)dashboardMonth=data.settings.dashboardMonth}else{for(const [key,store,method] of [['transactions',data.transactions,'saveTransaction'],['people',data.people,'savePerson'],['accounts',data.accounts,'saveAccount'],['reminders',data.reminders,'saveReminder']]){const existing=new Set((await LedgerDB.all(store)).map(x=>x.id));for(const row of data[key])if(!existing.has(row.id))await LedgerDB[method](row)}if(Array.isArray(data.categories))categories=[...new Set([...categories,...data.categories])];if(Array.isArray(data.investments))investments=[...new Set([...investments,...data.investments])]};localStorage.setItem('pocket-ledger-categories',JSON.stringify(categories));localStorage.setItem('pocket-ledger-investment-kinds',JSON.stringify(investments));localStorage.setItem('pocket-ledger-last-backup',new Date().toISOString());pendingBackup=null;$('#restoreOverlay').hidden=true;await reloadAppData();T=window.TRANSLATIONS[language]||window.TRANSLATIONS.en;initLabels();showScreen(currentScreen);showToast(T.restoreComplete)}catch(error){alert(T.restoreFailed);console.error(error)}}
  async function reloadAppData(){[people,transactions,reminders]=await Promise.all([LedgerDB.people(),LedgerDB.transactions(),LedgerDB.reminders()]);accounts=await LedgerDB.accounts();await normalizePeople();await initializeAccountsAndMigrate();refresh()}
  async function deleteAllData(){if(!confirm(T.deleteAllConfirm))return;const typed=prompt(T.typeDelete);if(typed!=='DELETE')return alert(T.deleteAllCancelled);for(const store of ['transactions','people','accounts','reminders'])await LedgerDB.clear(store);for(let i=localStorage.length-1;i>=0;i--){const key=localStorage.key(i);if(key?.startsWith('pocket-ledger-'))localStorage.removeItem(key)}transactions=[];people=[];reminders=[];accounts=[];categories=['Food','Travel','Fuel','Shopping','Bills','Rent','Medical','Education','Entertainment','Other'];investments=['SIP','Stocks','Gold','FD','Mutual Fund','Crypto','Other'];language='en';T=window.TRANSLATIONS.en;dashboardMonth=todayISO().slice(0,7);selectedAccountId='cash';applyTheme('auto');await LedgerDB.saveAccount({id:'cash',name:'Cash',kind:'cash',openingBalance:0});accounts=await LedgerDB.accounts();initLabels();refresh();showToast(T.allDataDeleted)}
  function renderDashboardRecent(){const rows=[...transactions].sort((a,b)=>b.date.localeCompare(a.date)||(b.createdAt||'').localeCompare(a.createdAt||'')||String(b.id||'').localeCompare(String(a.id||''))).slice(0,5);$('#dashboardRecentEmpty').hidden=rows.length>0;$('#dashboardRecent').innerHTML=rows.map(x=>{const isLoss=x.type==='Investment Loss',tone=x.kind==='credit'?'positive':x.kind==='debit'||isLoss?'negative':'transfer-tone',sign=x.kind==='credit'?'+':x.kind==='debit'||isLoss?'-':'';return `<div class="dashboard-activity-row"><span class="dashboard-activity-icon ${x.kind}">${x.kind==='credit'?'↙':x.kind==='debit'||isLoss?'↗':'↔'}</span><span><strong>${esc(x.type==='Transfer'?T.transfer:displayType(x.type))}</strong><small>${esc(dateLabel(x.date))}${x.person?.name?` · ${esc(x.person.name)}`:''}</small></span><strong class="${tone}">${sign}${rupees(x.amount)}</strong></div>`}).join('')}
  function renderInsights(list,metrics){const totals=new Map();list.filter(x=>x.type==='Daily Expense').forEach(x=>{const key=x.category||'Other';totals.set(key,(totals.get(key)||0)+Number(x.amount))});const highest=[...totals.entries()].sort((a,b)=>b[1]-a[1])[0];$('#highestExpenseInsight').textContent=highest?T.highestExpense.replace('{category}',categoryLabel(highest[0])).replace('{amount}',rupees(highest[1])):T.noDataThisMonth;const [y,m]=dashboardMonth.split('-').map(Number),now=new Date(),days=Number(y)===now.getFullYear()&&Number(m)===now.getMonth()+1?now.getDate():new Date(y,m,0).getDate();$('#averageExpenseInsight').textContent=T.averagePerDay.replace('{amount}',rupees(metrics.expense/Math.max(days,1)));$('#savingsRateInsight').textContent=T.savingsRate.replace('{percent}',metrics.income?Math.round(metrics.savings/metrics.income*100):0)}
  function renderDashboard(){updateDashboardMonthLabel();renderDashboardAccounts();const list=monthTransactionsFor(dashboardMonth),metrics=dashboardMetrics(list);$('#dashboardContent').hidden=false;$('#dashboardWelcome').hidden=transactions.length!==0;renderMonthlyCards();renderCategoryChart(list);renderSixMonthChart();renderDailyChart(list);renderDashboardOutstanding();renderInvestmentDashboard();renderDashboardReminders();renderDashboardRecent();renderInsights(list,metrics)}
  function isoDate(date){return `${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`}
  function reportPeriodRange(){const now=new Date(),period=$('#reportPeriod').value;let from,to;if(period==='thisMonth'){from=new Date(now.getFullYear(),now.getMonth(),1);to=new Date(now.getFullYear(),now.getMonth()+1,0)}else if(period==='lastMonth'){from=new Date(now.getFullYear(),now.getMonth()-1,1);to=new Date(now.getFullYear(),now.getMonth(),0)}else if(period==='thisYear'){from=new Date(now.getFullYear(),0,1);to=new Date(now.getFullYear(),11,31)}else if(period==='financialYear'){const y=now.getMonth()>=3?now.getFullYear():now.getFullYear()-1;from=new Date(y,3,1);to=new Date(y+1,2,31)}else{from=new Date(`${$('#reportFrom').value||todayISO()}T00:00:00`);to=new Date(`${$('#reportTo').value||todayISO()}T00:00:00`)}return {from:isoDate(from),to:isoDate(to),year:from.getFullYear()}}
  function fillReportFilters(){const acct=$('#reportAccount').value,cat=$('#reportCategory').value,person=$('#reportPerson').value;$('#reportAccount').innerHTML=`<option value="">${esc(T.allAccounts)}</option>`+orderedAccounts().map(x=>`<option value="${esc(x.id)}">${esc(x.name)}</option>`).join('');$('#reportCategory').innerHTML=`<option value="">${esc(T.allCategories)}</option>`+categories.map(x=>`<option value="${esc(x)}">${esc(T[x.toLowerCase().replaceAll(' ','')]||x)}</option>`).join('');$('#reportPerson').innerHTML=`<option value="">${esc(T.allPeople)}</option>`+people.map(x=>`<option value="${esc(x.id)}">${esc(x.name)}</option>`).join('');if([...$('#reportAccount').options].some(x=>x.value===acct))$('#reportAccount').value=acct;if([...$('#reportCategory').options].some(x=>x.value===cat))$('#reportCategory').value=cat;if([...$('#reportPerson').options].some(x=>x.value===person))$('#reportPerson').value=person}
  function filteredReportTransactions({includeUdharOverride=false,excludeTransfers=true,ignorePeriod=false}={}){const {from,to}=reportPeriodRange(),account=$('#reportAccount').value,type=$('#reportType').value,category=$('#reportCategory').value,person=$('#reportPerson').value,includeUdhar=includeUdharOverride||$('#includeUdhar').checked;return transactions.filter(x=>{if(!ignorePeriod&&(x.date<from||x.date>to))return false;if(excludeTransfers&&x.kind==='transfer')return false;if(!includeUdhar&&udharTypes.includes(x.type))return false;if(account&&!(x.kind==='transfer'?x.fromAccountId===account||x.toAccountId===account:x.accountId===account))return false;if(type!=='all'&&x.kind!==type)return false;if(category&&x.category!==category&&x.investmentKind!==category)return false;if(person&&x.person?.id!==person)return false;return true})}
  function accountBalanceAt(accountId,dateInclusive){const account=accounts.find(x=>x.id===accountId);let balance=Number(account?.openingBalance)||0;for(const x of transactions){if(x.date>dateInclusive)continue;if(x.kind==='transfer'){if(x.fromAccountId===accountId)balance-=Number(x.amount)||0;if(x.toAccountId===accountId)balance+=Number(x.amount)||0;continue}if(x.type==='Investment Loss'||x.kind==='noncash'||x.accountId!==accountId)continue;if(x.kind==='credit')balance+=Number(x.amount)||0;else if(x.kind==='debit')balance-=Number(x.amount)||0}return balance}
  function periodBoundaryBalance(dateBefore){return accounts.filter(a=>!$('#reportAccount').value||a.id===$('#reportAccount').value).reduce((sum,a)=>sum+accountBalanceAt(a.id,dateBefore),0)}
  function setReportCsv(rows){reportRows=rows}
  function reportSummary(){const rows=filteredReportTransactions(),sum=test=>rows.filter(test).reduce((s,x)=>s+(Number(x.amount)||0),0),udharCredit=x=>['Udhar Taken','Udhar Received Back'].includes(x.type),udharDebit=x=>['Udhar Given','Udhar Repaid'].includes(x.type),income=sum(x=>['Salary','Side Income','Investment Profit'].includes(x.type)||( $('#includeUdhar').checked&&udharCredit(x))),expense=sum(x=>x.type==='Daily Expense'||($('#includeUdhar').checked&&udharDebit(x))),investment=sum(x=>x.type==='Investment'),loss=sum(x=>x.type==='Investment Loss'),savings=income-expense-investment,{from,to}=reportPeriodRange(),before=new Date(`${from}T00:00:00`);before.setDate(before.getDate()-1);const opening=periodBoundaryBalance(isoDate(before)),closing=periodBoundaryBalance(to);const metrics=[[T.income,income,'positive'],[T.expense,expense,'negative'],[T.investment,investment,'investment-tone'],[T.savings,savings,savings<0?'negative':'positive'],[T.savingsRate,`${income?Math.round(savings/income*100):0}%`,''],[T.investmentLoss,loss,'negative'],[T.openingBalance,opening,''],[T.closingBalance,closing,'']];setReportCsv([[T.reportMetric,T.amount],...metrics.map(([label,value])=>[label,typeof value==='number'?formatMoney(value):value])]);return `<div class="report-period-caption">${T.period}: ${esc(dateLabel(from,{day:'numeric',month:'short',year:'numeric'}))} – ${esc(dateLabel(to,{day:'numeric',month:'short',year:'numeric'}))}</div><div class="report-summary-grid">${metrics.map(([label,value,tone])=>`<article><span>${esc(label)}</span><strong class="${tone}">${typeof value==='number'?rupees(value):value}</strong></article>`).join('')}</div><p class="report-generated">${T.reportGenerated}: ${esc(new Date().toLocaleDateString(language==='gu'?'gu-IN':'en-IN'))}</p>`}
  function reportCategory(){const rows=filteredReportTransactions().filter(x=>x.type==='Daily Expense'||($('#includeUdhar').checked&&udharTypes.includes(x.type)));const totals=new Map();for(const x of rows){const key=x.category|| (udharTypes.includes(x.type)?T.udhar:'Other');totals.set(key,(totals.get(key)||0)+(Number(x.amount)||0))}const total=[...totals.values()].reduce((s,x)=>s+x[1],0),items=[...totals].sort((a,b)=>b[1]-a[1]);setReportCsv([[T.category,T.amount,T.percentage],...items.map(([k,v])=>[categoryLabel(k),formatMoney(v),`${total?Math.round(v/total*100):0}%`])]);if(reportCategoryDrill){const entries=rows.filter(x=>(x.category||(udharTypes.includes(x.type)?T.udhar:'Other'))===reportCategoryDrill).sort(transactionOrder).reverse();setReportCsv([[T.date,T.description,T.amount],...entries.map(x=>[x.date,reportDescription(x),formatMoney(x.amount)])]);return `<button class="back-button" id="backCategoryReport">← ${T.backToCategories}</button><h3>${esc(categoryLabel(reportCategoryDrill))}</h3>${pagedReportTable(entries,[[T.date,x=>dateLabel(x.date,{day:'numeric',month:'short',year:'numeric'})],[T.description,x=>reportDescription(x)],[T.amount,x=>rupees(x.amount)]],'category')}`};return `<div class="report-bar-list">${items.map(([name,value])=>`<button type="button" class="report-category-row" data-category-drill="${esc(name)}"><span>${esc(categoryLabel(name))}</span><strong>${rupees(value)}</strong><i><b style="width:${total?value/total*100:0}%"></b></i><small>${total?Math.round(value/total*100):0}%</small></button>`).join('')||`<p>${T.noReportData}</p>`}</div>`}
  function renderTrendReport(){const year=reportPeriodRange().year,rows=[];for(let month=0;month<12;month++){const key=`${year}-${String(month+1).padStart(2,'0')}`,items=filteredReportTransactions({excludeTransfers:true,ignorePeriod:true}).filter(x=>x.date.slice(0,7)===key),income=items.filter(x=>['Salary','Side Income','Investment Profit'].includes(x.type)).reduce((s,x)=>s+Number(x.amount||0),0),expense=items.filter(x=>x.type==='Daily Expense').reduce((s,x)=>s+Number(x.amount||0),0),investment=items.filter(x=>x.type==='Investment').reduce((s,x)=>s+Number(x.amount||0),0);rows.push({month:new Date(year,month,1).toLocaleDateString(language==='gu'?'gu-IN':'en-IN',{month:'short'}),income,expense,investment})}setReportCsv([[T.month,T.income,T.expense,T.investment],...rows.map(x=>[x.month,formatMoney(x.income),formatMoney(x.expense),formatMoney(x.investment)])]);const max=Math.max(1,...rows.flatMap(x=>[x.income,x.expense,x.investment])),bars=rows.map((x,i)=>{const xx=20+i*55,scale=92/max;return `<rect x="${xx}" y="${108-x.income*scale}" width="10" height="${x.income*scale}" fill="#16875d"/><rect x="${xx+12}" y="${108-x.expense*scale}" width="10" height="${x.expense*scale}" fill="#dc5a55"/><rect x="${xx+24}" y="${108-x.investment*scale}" width="10" height="${x.investment*scale}" fill="#4d7ecc"/><text x="${xx+12}" y="126" text-anchor="middle">${esc(x.month)}</text>`}).join('');return `<h3>${year}</h3><div class="report-chart"><svg viewBox="0 0 690 138" preserveAspectRatio="none" aria-label="${esc(T.monthlyTrend)}"><path d="M12 108H675" stroke="var(--line)"/>${bars}</svg><div class="chart-legend"><span><i class="legend-income"></i>${T.income}</span><span><i class="legend-expense"></i>${T.expense}</span><span><i class="legend-investment"></i>${T.investment}</span></div></div>${reportTable(rows,[[T.month,x=>x.month],[T.income,x=>rupees(x.income)],[T.expense,x=>rupees(x.expense)],[T.investment,x=>rupees(x.investment)]])}`}
  function reportDescription(x){return `${displayType(x.type)}${x.person?.name?` · ${x.person.name}`:''}${x.note?` · ${x.note}`:''}`}
