  function renderAccountStatement(){const id=$('#reportAccount').value||accounts[0]?.id;if(!id){setReportCsv([]);return T.noReportData}const {from,to}=reportPeriodRange(),account=accounts.find(x=>x.id===id),opening=accountBalanceAt(id,isoDate(new Date(new Date(`${from}T00:00:00`).setDate(new Date(`${from}T00:00:00`).getDate()-1)))),all=transactions.filter(x=>x.date>=from&&x.date<=to&&(x.kind==='transfer'?x.fromAccountId===id||x.toAccountId===id:x.accountId===id)&&x.type!=='Investment Loss'&&x.kind!=='noncash').sort(transactionOrder);let running=opening;const lines=all.map(x=>{const credit=x.kind==='transfer'?(x.toAccountId===id?Number(x.amount):0):x.kind==='credit'?Number(x.amount):0,debit=x.kind==='transfer'?(x.fromAccountId===id?Number(x.amount):0):x.kind==='debit'?Number(x.amount):0;running+=credit-debit;return {date:x.date,description:reportDescription(x),credit,debit,balance:running}});const closing=lines.at(-1)?.balance??opening;setReportCsv([[T.date,T.description,T.credit,T.debit,T.balance],...lines.map(x=>[x.date,x.description,formatMoney(x.credit),formatMoney(x.debit),formatMoney(x.balance)])]);return `<div class="report-period-caption">${esc(account?.name||'')} · ${T.openingBalance}: ${rupees(opening)}</div>${reportTable(lines,[[T.date,x=>dateLabel(x.date,{day:'numeric',month:'short',year:'numeric'})],[T.description,x=>x.description],[T.credit,x=>x.credit?rupees(x.credit):'—'],[T.debit,x=>x.debit?rupees(x.debit):'—'],[T.runningBalance,x=>rupees(x.balance)]])}<p class="report-closing">${T.closingBalance}: <strong>${rupees(closing)}</strong></p>`}
  function renderPersonStatement(){const id=$('#reportPerson').value;if(!id){setReportCsv([]);return `<p>${T.selectPersonReport}</p>`}const person=people.find(x=>x.id===id),{from,to}=reportPeriodRange(),all=personUdharTransactions(id).sort(transactionOrder),opening=all.filter(x=>x.date<from).reduce((s,x)=>s+udharDelta(x),0);let running=opening;const rows=all.filter(x=>x.date>=from&&x.date<=to).map(x=>({date:x.date,type:displayType(x.type),note:x.note||'',amount:Number(x.amount)||0,delta:udharDelta(x),id:x.id})).map(x=>{running+=x.delta;return {...x,balance:running}});const finalNet=outstanding(id);setReportCsv([[T.date,T.type,T.amount,T.runningBalance,T.note],...rows.map(x=>[x.date,x.type,formatMoney(x.amount),formatMoney(x.balance),x.note])]);const status=finalNet>0?`${T.youWillReceive} ${rupees(finalNet)}`:finalNet<0?`${T.youHaveToGive} ${rupees(Math.abs(finalNet))}`:T.settledAmount;return `<h3>${esc(person?.name||'')}</h3>${reportTable(rows,[[T.date,x=>dateLabel(x.date,{day:'numeric',month:'short',year:'numeric'})],[T.type,x=>x.type],[T.amount,x=>rupees(x.amount)],[T.runningBalance,x=>{const n=x.balance;return n<0?`${T.youHaveToGive} ${rupees(Math.abs(n))}`:n>0?`${T.youWillReceive} ${rupees(n)}`:T.settledAmount}],[T.note,x=>x.note]])}<p class="report-closing">${T.finalOutstanding}: <strong class="${finalNet<0?'negative':'positive'}">${esc(status)}</strong></p>`}
  function renderInvestmentReport(){const {from,to}=reportPeriodRange(),items=transactions.filter(x=>['Investment','Investment Profit','Investment Loss'].includes(x.type)&&x.date>=from&&x.date<=to),map=new Map();for(const x of items){const name=x.investmentName||T.noInvestmentNames;if(!map.has(name))map.set(name,{name,kind:x.investmentKind||'Other',invested:0,profit:0,loss:0,last:x.date});const r=map.get(name);r.kind=x.investmentKind||r.kind;r.last=x.date>r.last?x.date:r.last;if(x.type==='Investment')r.invested+=Number(x.amount)||0;if(x.type==='Investment Profit')r.profit+=Number(x.amount)||0;if(x.type==='Investment Loss')r.loss+=Number(x.amount)||0}const rows=[...map.values()].map(x=>({...x,net:x.profit-x.loss}));setReportCsv([[T.investmentName,T.investmentKind,T.invested,T.profit,T.loss,T.netInvestmentResult,T.lastEntry],...rows.map(x=>[x.name,x.kind,formatMoney(x.invested),formatMoney(x.profit),formatMoney(x.loss),formatMoney(x.net),x.last])]);return reportTable(rows,[[T.investmentName,x=>x.name],[T.investmentKind,x=>T[x.kind.toLowerCase().replaceAll(' ','')]||x.kind],[T.invested,x=>rupees(x.invested)],[T.profit,x=>rupees(x.profit)],[T.loss,x=>rupees(x.loss)],[T.netInvestmentResult,x=>rupees(x.net)],[T.lastEntry,x=>dateLabel(x.last)]])}
